INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1201, 'Genesis 41:49', 'Genesis', 41, 49, '&nbsp;دا غله دومره زياته وه چې يوسف يې تلل پرېښودل. دا د سمندر په غاړه د شګو په شان ډېره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1202, 'Genesis 41:50', 'Genesis', 41, 50, '&nbsp;د قحط د کالونو نه مخکښې د يوسف د اسنت نه دوه زامن پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1203, 'Genesis 41:51', 'Genesis', 41, 51, '&nbsp;هغۀ ووئيل، ”خُدائ پاک زما ټولې سختۍ او زما د پلار ټول خاندان زما نه هېر کړے دے.“ نو يوسف په خپل مشر زوئ منسى نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1204, 'Genesis 41:52', 'Genesis', 41, 52, '&nbsp;هغۀ دا هم ووئيل، ”خُدائ پاک زما د تکليف په مُلک کښې ما له بچى راکړى دى.“ نو هغۀ په خپل دوېم زوئ اِفرائيم نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1205, 'Genesis 41:53', 'Genesis', 41, 53, '&nbsp;د مِصر د مُلک د آبادۍ هغه اووۀ کالونه ختم شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1206, 'Genesis 41:54', 'Genesis', 41, 54, '&nbsp;او د قحط اووۀ کالونه شروع شول هم هغه شان لکه چې څنګه يوسف فرمائيلى وُو. په نورو ټولو مُلکونو کښې قحط وو، خو د مِصر په ټول مُلک کښې خوراک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1207, 'Genesis 41:55', 'Genesis', 41, 55, '&nbsp;چې کله مِصريان ډېر زيات اوږى شول، دوئ فِرعون ته د خوراک دپاره فرياد وکړو. نو هغۀ هغوئ له حُکم ورکړو چې، ”يوسف له لاړ شئ او هم هغسې وکړئ چې څنګه هغه تاسو ته وائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1208, 'Genesis 41:56', 'Genesis', 41, 56, '&nbsp;قحط سخت شو او په ټول مُلک کښې خور شو، نو يوسف ټول ګودامونه کولاو کړل او په مِصريانو به يې غله خرڅوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1209, 'Genesis 41:57', 'Genesis', 41, 57, '&nbsp;د يوسف نه غله اخستلو دپاره د ټولې دُنيا نه خلق مِصر ته راتلل، ځکه چې قحط په هر ځائ کښې ډېر سخت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1210, 'Genesis 42:1', 'Genesis', 42, 1, '&nbsp;چې کله يعقوب خبر شو چې په مِصر کښې غله شته، هغۀ خپلو زامنو ته ووئيل چې، ”ولې يو بل ته ګورئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1211, 'Genesis 42:2', 'Genesis', 42, 2, '&nbsp;ګورئ، ما اورېدلى دى چې په مِصر کښې غله شته، هلته لاړ شئ او لږه واخلئ چې ژوندى پاتې شُو او د لوږې نه مړۀ نۀ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1212, 'Genesis 42:3', 'Genesis', 42, 3, '&nbsp;نو د يوسف لس مېرنى وروڼه د غلې اخستلو دپاره مِصر ته لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1213, 'Genesis 42:4', 'Genesis', 42, 4, '&nbsp;خو يعقوب د يوسف سکه ورور بنيامين د هغوئ سره ونۀ لېږلو، ځکه چې هغه په دې يرېدو چې څۀ نقصان به ورته ورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1214, 'Genesis 42:5', 'Genesis', 42, 5, '&nbsp;نو د يعقوب زامن د نورو خلقو سره غلې اخستلو دپاره راغلل ځکه چې د کنعان په مُلک کښې قحط وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1215, 'Genesis 42:6', 'Genesis', 42, 6, '&nbsp;يوسف د مِصر د مُلک د مشر په توګه د ټولې دُنيا په خلقو باندې غله خرڅوله. نو د يوسف وروڼه راغلل او د هغۀ په مخکښې ټيټ شول او خپل سرونه يې ورته په زمکه ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1216, 'Genesis 42:7', 'Genesis', 42, 7, '&nbsp;يوسف خپل وروڼه وليدل، هغۀ دوئ وپېژندل، خو ځان يې داسې کړو لکه چې هډو دوئ پېژنى نه. او د هغوئ سره يې سختې خبرې کولې، ”تاسو د کوم ځائ نه راغلى يئ؟“ هغوئ ورته ووئيل، ”صاحِبه، مونږ د خوراک اخستلو دپاره د کنعان نه راغلى يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1217, 'Genesis 42:8', 'Genesis', 42, 8, '&nbsp;اګر چې يوسف خپل وروڼه وپېژندل، خو هغوئ هغه ونۀ پېژندو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1218, 'Genesis 42:9', 'Genesis', 42, 9, '&nbsp;هغۀ ته هغه خوبونه راياد شول کوم يې چې د هغوئ په حقله ليدلى وُو او ورته يې ووئيل، ”تاسو جاسوسان يئ، تاسو زمونږ د مُلک کمزورى معلومولو له راغلى يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1219, 'Genesis 42:10', 'Genesis', 42, 10, '&nbsp;هغوئ جواب ورکړو، ”نه، صاحِبه، مونږ ستا خِدمتګاران د خوراک اخستلو دپاره راغلى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1220, 'Genesis 42:11', 'Genesis', 42, 11, '&nbsp;مونږ ټول د يو سړى زامن يُو. صاحِبه، مونږ جاسوسان نۀ يُو، مونږ صحيح خلق يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1221, 'Genesis 42:12', 'Genesis', 42, 12, '&nbsp;يوسف ورته ووئيل، ”نه، تاسو زمونږ د مُلک کمزورى معلومولو له راغلى يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1222, 'Genesis 42:13', 'Genesis', 42, 13, '&nbsp;هغوئ ورته ووئيل، ”صاحِبه، مونږ دولس وروڼه وُو. د کنعان په مُلک کښې د يو سړى زامن يُو. يو ورور مو مړ دے او کشرے ورور مو اوس د خپل پلار سره دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1223, 'Genesis 42:14', 'Genesis', 42, 14, '&nbsp;يوسف ورته ووئيل، ”هم دغه شان ده لکه چې څنګه ما ووئيل تاسو جاسوسان يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1224, 'Genesis 42:15', 'Genesis', 42, 15, '&nbsp;نو اوس زۀ تاسو په دې طريقې سره معلوموم چې په رښتيا سره تاسو څوک يئ. زۀ د فِرعون په سر قسم کوم چې تاسو به تر هغې پورې لاړ نۀ شئ چې ترڅو ستاسو کشرے ورور دلته راغلے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1225, 'Genesis 42:16', 'Genesis', 42, 16, '&nbsp;تاسو يو کس لاړ شئ او هغه راولئ. تاسو باقى نور به په قېدخانه کښې واچولے شئ چې ستاسو دا خبره معلومه کړے شى چې تاسو رښتيا وايئ کۀ نۀ. ګنې، د فِرعون په سر مې قسم دے چې تاسو په رښتيا جاسوسان يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1226, 'Genesis 42:17', 'Genesis', 42, 17, '&nbsp;بيا درې ورځې يې هغوئ ټول په قېدخانه کښې بند کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1227, 'Genesis 42:18', 'Genesis', 42, 18, '&nbsp;په درېمه ورځ يوسف هغوئ ته ووئيل، ”زۀ د خُدائ پاک نه يرېږم او زۀ به تاسو په يو شرط ژوندى پرېږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1228, 'Genesis 42:19', 'Genesis', 42, 19, '&nbsp;چې دا ثابِته شى چې تاسو رښتونى يئ، ستاسو نه به يو کس په قېدخانه کښې بند وى، باقى نور ټول تلے شئ او چې کومه غله تاسو اخستې ده هغه خپلو قحط وهلو خلقو له يوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1229, 'Genesis 42:20', 'Genesis', 42, 20, '&nbsp;خو تاسو به خامخا خپل کشرے ورور ما له راولئ. د دې نه به دا ثابِته شى چې تاسو رښتيا وايئ او زۀ به تاسو نۀ وژنم.“ نو هغوئ دې ته راضى شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1230, 'Genesis 42:21', 'Genesis', 42, 21, '&nbsp;او يو بل ته يې ووئيل، ”دا اوس چې مونږ کړېږُو دا د هغې نتيجه ده چې مونږ د خپل ورور سره څۀ کړى وُو، هغه چې په کوم لوئ مصيبت کښې مونږ وليدلو چې کله هغۀ مِنت زارى کوله، خو مونږ وانۀ ورېدله. دا ځکه اوس مونږ په دې تکليف کښې راګېر يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1231, 'Genesis 42:22', 'Genesis', 42, 22, '&nbsp;روبين ووئيل، ”ما تاسو ته وئيل چې هلک له تکليف مۀ ورکوئ، خو تاسو وانۀ ورېدل. او اوس به زمونږ نه د هغۀ د وينې حِساب غوښتے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1232, 'Genesis 42:23', 'Genesis', 42, 23, '&nbsp;هغوئ ته پته ونۀ لګېده چې يوسف د دوئ په خبرو پوهيږى، ځکه چې هغۀ د هغوئ سره د يو ترجمان په ذريعه خبرې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1233, 'Genesis 42:24', 'Genesis', 42, 24, '&nbsp;يوسف د هغوئ نه لاړو او په ژړا شو. چې کله هغۀ د ژړا نه پس خبرې کولې نو راواپس شو، شمعون يې رابېل کړو او د هغوئ په مخکښې يې وتړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1234, 'Genesis 42:25', 'Genesis', 42, 25, '&nbsp;يوسف حُکم ورکړو چې د هغۀ د وروڼو بوجۍ د غلې نه ډکې کړئ، د هر يو کس روپۍ واپس د هغۀ په بوجۍ کښې کېږدئ او هغوئ له د سفر دپاره خوراک هم ورکړئ. او هم دغه شان يې ورسره وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1235, 'Genesis 42:26', 'Genesis', 42, 26, '&nbsp;د هغۀ وروڼو چې کومه غله اخستې وه د هغې نه يې خپل خرونه بار کړل او بيا دوئ لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1236, 'Genesis 42:27', 'Genesis', 42, 27, '&nbsp;چې کله په سرائى کښې يو کس خپله بوجۍ کولاو کړه چې خپل خرۀ له خوراک ورکړى نو د بوجۍ په خولۀ کښې يې روپۍ وليدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1237, 'Genesis 42:28', 'Genesis', 42, 28, '&nbsp;هغۀ خپل وروڼه راوغوښتل، ”دېخوا وګورئ، ما ته يې خپلې روپۍ واپس کړې دى، دا دى زما په بوجۍ کښې دى.“ د هغوئ ساه ډُوبه شوه او ويرېدل او هغوئ د يو بل نه پوښتنه وکړه چې، ”دې خُدائ پاک لا مونږ سره څۀ وکړل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1238, 'Genesis 42:29', 'Genesis', 42, 29, '&nbsp;چې کله دوئ په کنعان کښې خپل پلار يعقوب له راغلل، هغوئ هغۀ ته هر څۀ ووئيل چې د هغوئ سره شوى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1239, 'Genesis 42:30', 'Genesis', 42, 30, '&nbsp;”د مِصر مشر مونږ سره سختې خبرې کولې او هغۀ په مونږ اِلزام ولګولو چې مونږ د هغۀ په مُلک کښې جاسوسى کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1240, 'Genesis 42:31', 'Genesis', 42, 31, '&nbsp;مونږ ورته ووئيل چې مونږ جاسوسان نۀ يُو مونږ صحيح خلق يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1241, 'Genesis 42:32', 'Genesis', 42, 32, '&nbsp;مونږ ټول دولس وروڼه د يو پلار زامن وُو. يو ورور مو مړ دے او کشرے ورور مو د پلار سره په کنعان کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1242, 'Genesis 42:33', 'Genesis', 42, 33, '&nbsp;هغه سړى مونږ ته ووئيل، يو کس زما سره پاتې شئ نو ما ته به پته ولګى چې تاسو صحيح خلق يئ، او باقى نور به خپلو نهَرو کورَنو له غله واخلئ او لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1243, 'Genesis 42:34', 'Genesis', 42, 34, '&nbsp;خپل کشرے ورور ما له راولئ. بيا به ما ته پته ولګى چې تاسو جاسوسان نۀ يئ او صحيح خلق يئ، زۀ به تاسو له خپل ورور در‌واپس کړم او بيا تاسو دلته پاتې شئ او سوداګرى کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1244, 'Genesis 42:35', 'Genesis', 42, 35, '&nbsp;نو چې کله هغوئ خپلې بوجۍ تشولې نو هر يو کس د روپو کڅوړې وموندلې، او چې روپۍ يې وليدلې، نو هغوئ او د هغوئ پلار ويرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1245, 'Genesis 42:36', 'Genesis', 42, 36, '&nbsp;خپل پلار يعقوب هغوئ ته ووئيل، ”تاسو ما د ټولو زامنو نه خلاصول غواړئ څۀ؟ يوسف لاړو، شمعون لاړو، او اوس به تاسو بنيامين هم بوځئ. دا ټول تکليفونه په ما راغلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1246, 'Genesis 42:37', 'Genesis', 42, 37, '&nbsp;روبين خپل پلار ته ووئيل، ”کۀ بنيامين ما واپس تا له رانۀ وستلو، نو تۀ زما دوه زامن ووژنه. بنيامين زما په حواله کړه او زۀ به يې واپس تا له راولم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1247, 'Genesis 42:38', 'Genesis', 42, 38, '&nbsp;خو يعقوب ووئيل، ”زما زوئ به ستاسو سره نۀ ځى، د هغۀ ورور مړ دے او هغه اېک يواځې پاتې دے. په لار کښې به په هغۀ څۀ وشى. زۀ ضعيف سړے يم او چې تاسو ما په کوم غم آخته کوئ نو ما سپين‌ږيرے به قبر ته ولېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1248, 'Genesis 43:1', 'Genesis', 43, 1, '&nbsp;نو په کنعان کښې قحط نور هم سخت شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1249, 'Genesis 43:2', 'Genesis', 43, 2, '&nbsp;او چې کله د يعقوب کورنۍ ټوله غله وخوړله کومه چې د مِصر نه راوړلے شوې وه، يعقوب خپلو زامنو ته وفرمائيل، ”بيا لاړ شئ او زمونږ دپاره لږه نوره غله راوړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1250, 'Genesis 43:3', 'Genesis', 43, 3, '&nbsp;يهوداه هغۀ ته ووئيل، ”هغه سړى مونږ ته په ټينګه خبردارے راکړے دے چې مونږ د ځان سره خپل ورور نۀ وى راوستلے نو مونږ د هغۀ په دربار کښې نۀ شُو حاضرېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1251, 'Genesis 43:4', 'Genesis', 43, 4, '&nbsp;کۀ تۀ مونږ سره زمونږ ورور لېږل غواړې، نو مونږ به لاړ شُو او ستا دپاره به خوراک واخلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1252, 'Genesis 43:5', 'Genesis', 43, 5, '&nbsp;او کۀ تۀ نۀ غواړې، نو مونږ به نۀ ځُو، ځکه چې هغه سړى مونږ ته وئيلى دى چې مونږ سره خپل ورور نۀ وى نو مونږ د هغۀ په دربار کښې نۀ شُو حاضرېدلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1253, 'Genesis 43:6', 'Genesis', 43, 6, '&nbsp;يعقوب ورته وفرمائيل، ”تاسو زۀ په دومره سخت تکليف کښې ولې آخته کړے يم چې هغه سړى ته مو ووئيل چې زمونږ بل ورور هم شته؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1254, 'Genesis 43:7', 'Genesis', 43, 7, '&nbsp;هغوئ جواب ورکړو، ”هغه سړى زمونږ او زمونږ د خاندان په حقله تپوسونه کول چې، ستاسو پلار تر اوسه پورې ژوندے دے څۀ؟ ستاسو بل ورور شته څۀ؟ مونږ خو صِرف د هغۀ د تپوسونو جواب ورکولو. مونږ ته څۀ پته وه چې هغه به مونږ ته وائى چې تاسو د ځان سره خپل ورور هم راولئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1255, 'Genesis 43:8', 'Genesis', 43, 8, '&nbsp;يهوداه خپل پلار ته ووئيل، ”دا هلک ما سره ولېږه او مونږ به سمدستى لاړ شُو. هسې نه چې مونږ او تاسو سره د خپلو ماشومان او د لوږې نه مړۀ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1256, 'Genesis 43:9', 'Genesis', 43, 9, '&nbsp;زۀ به په خپله د هغۀ حِفاظت کوم او تۀ د هغۀ ذمه وارى زما په غاړه کولے شې. کۀ زۀ دے تا له واپس روغ او سلامت رانۀ ولم، نو زۀ به همېشه تا ته ملامته يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1257, 'Genesis 43:10', 'Genesis', 43, 10, '&nbsp;کۀ مونږ دومره وخت ضائع کړے نۀ وے، نو مونږ به هلته تلى وو او تر اوسه پورې به دوه ځل واپس هم راغلى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1258, 'Genesis 43:11', 'Genesis', 43, 11, '&nbsp;خپل پلار هغوئ ته وفرمائيل، ”کۀ هم دغه شان کيږى، نو د دې مُلک د ټولو نه ښۀ څيزونه په خپلو بوجو کښې کېږدئ او هغه مشر له يې په تُحفه کښې يوسئ، لږ عطر، شات، خوشبودارې مصالحې، پسته او بادام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1259, 'Genesis 43:12', 'Genesis', 43, 12, '&nbsp;د خپل ځان سره يو په دوه روپۍ يوسئ، ځکه چې کومې روپۍ ستاسو د بوجو په خُلو کښې واپس کړے شوې وې تاسو هغه خامخا واپس کړئ. کېدے شى چې په غلطۍ سره داسې شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1260, 'Genesis 43:13', 'Genesis', 43, 13, '&nbsp;خپل ورور روان کړئ او سمدستى هغه سړى له واپس لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1261, 'Genesis 43:14', 'Genesis', 43, 14, '&nbsp;قادر خُدائ دې هغه سړے په تاسو مِهربانه کړى، نو چې هغه بنيامين او هغه ستاسو بل ورور دواړه تاسو ته واپس کړى. خو کۀ زما بچى خامخا مړۀ کيږى، نو مړۀ دې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1262, 'Genesis 43:15', 'Genesis', 43, 15, '&nbsp;نو د هغۀ زامنو هغه تُحفې او يو په دوه روپۍ واخستلې او مِصر ته د بنيامين سره روان شول. او هلته د يوسف په حضور کښې پېش شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1263, 'Genesis 43:16', 'Genesis', 43, 16, '&nbsp;چې کله يوسف بنيامين د هغوئ سره وليدلو، نو هغۀ د خپل کور مشر خِدمتګار ته ووئيل، ”دا سړى زما کور ته بوځه. د غرمې روټۍ به دوئ زما سره وخورى، نو يو څاروے حلال کړه او تيار يې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1264, 'Genesis 43:17', 'Genesis', 43, 17, '&nbsp;نو خِدمتګار هم هغه شان وکړل چې څنګه ورته حُکم شوے وو او هغه کسان يې د يوسف کور ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1265, 'Genesis 43:18', 'Genesis', 43, 18, '&nbsp;چې کله يې هغوئ کور ته راروان کړى وُو، هغوئ ويرېدل او فکر يې کولو چې، ”مونږ ته په وړومبى ځل چې کومې روپۍ واپس کړے شوې وې د هغې په وجه يې دلته راروان کړى يُو. دوئ به ناڅاپى په مونږ حمله وکړى، زمونږ خرۀ به بوځى او مونږ به خپل غلامان کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1266, 'Genesis 43:19', 'Genesis', 43, 19, '&nbsp;نو د کور د دروازې سره هغوئ مشر خِدمتګار ته ووئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1267, 'Genesis 43:20', 'Genesis', 43, 20, '&nbsp;”اے صاحِبه، مونږ دلته يو ځل مخکښې د خوراک اخستلو دپاره راغلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1268, 'Genesis 43:21', 'Genesis', 43, 21, '&nbsp;مونږ چې کله سرائى ته ورسېدو، مونږ خپلې بوجۍ کولاو کړې، نو هر يو کس خپلې ټولې روپۍ د خپلې خپلې بوجۍ په خولۀ کښې وموندلې. مونږ هغه د ځان سره واپس راوړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1269, 'Genesis 43:22', 'Genesis', 43, 22, '&nbsp;مونږ ځان سره د نور خوراک اخستلو دپاره نورې روپۍ هم راوړې دى. مونږ ته پته نشته چې هغه روپۍ زمونږ په بوجو کښې چا واپس اېښې وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1270, 'Genesis 43:23', 'Genesis', 43, 23, '&nbsp;د خِدمتګارانو مشر ورته ووئيل، ”خېر به شى، مۀ يرېږئ. ستاسو او ستاسو د پلار خُدائ پاک درله هغه روپۍ ستاسو په بوجو کښې اېښې وې. ستاسو روپۍ ما ته مِلاو شوې.“ بيا هغۀ شمعون هغوئ له راوستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1271, 'Genesis 43:24', 'Genesis', 43, 24, '&nbsp;هغه خِدمتګار دوئ دننه کور ته بوتلل او هغوئ له يې د پښو وينځلو دپاره اوبۀ ورکړې او د هغوئ خرونو ته يې واښۀ واچول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1272, 'Genesis 43:25', 'Genesis', 43, 25, '&nbsp;هغوئ خپلې تُحفې تيارې کړې چې يوسف ته يې پېش کړى چې کله هغه د غرمې راورسيږى، ځکه چې هغوئ ته وئيلى شوى وُو چې هغوئ به د هغۀ سره روټۍ خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1273, 'Genesis 43:26', 'Genesis', 43, 26, '&nbsp;چې کله يوسف کور ته راغلو، هغوئ تُحفې دننه کور ته هغۀ له يوړې او د هغۀ په مخکښې ته ټيټ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1274, 'Genesis 43:27', 'Genesis', 43, 27, '&nbsp;هغۀ د هغوئ نه د خېر خېريت پوښتنه وکړه او بيا يې ورته ووئيل، ”تاسو ما ته د خپل ضعيف پلار په حقله وئيلى وُو، هغه څنګه دے؟ هغه ژوندے دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1275, 'Genesis 43:28', 'Genesis', 43, 28, '&nbsp;هغوئ ورته ووئيل، ”زمونږ پلار ستاسو خِدمتګار تر اوسه پورې ژوندے دے او روغ جوړ دے.“ او هغوئ د هغۀ په مخکښې خپل سرونه ټيټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1276, 'Genesis 43:29', 'Genesis', 43, 29, '&nbsp;چې کله يوسف د خپلې مور زوئ، خپل سکه ورور بنيامين وليدو، هغۀ وفرمائيل، ”نو دا ستاسو کشرے ورور دے، چې تاسو د هغۀ په حقله ما ته وئيلى وُو؟ زما زويه، خُدائ پاک دې په تا مِهربانه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1277, 'Genesis 43:30', 'Genesis', 43, 30, '&nbsp;بيا يوسف فوراً لاړو، ځکه چې د خپل ورور په ليدو د هغۀ زړۀ نرم شو. او د ژړا نه يې سترګې ډکې شوې، نو هغه خپلې کوټې ته لاړو او وې ژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1278, 'Genesis 43:31', 'Genesis', 43, 31, '&nbsp;د هغې نه پس چې کله هغۀ مخ ووينځلو، هغه بهر راغلو او خپل زړۀ يې کلک کړو، هغۀ حُکم وکړو چې روټۍ راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1279, 'Genesis 43:32', 'Genesis', 43, 32, '&nbsp;يوسف په يو دسترخوان روټۍ ته ناست وو او په بل باندې د هغۀ وروڼه ناست وُو. او چې کومو مِصريانو هلته روټۍ خوړله، هغوئ ته يې په بل ځائ کښې روټۍ کېښودله، ځکه چې هغوئ د عبرانيانو سره روټۍ خوړل حرام ګڼل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1280, 'Genesis 43:33', 'Genesis', 43, 33, '&nbsp;د هغۀ وروڼه په دسترخوان ناست وُو، د هغوئ د عُمر په حِساب سره د مشر نه کشر پورې يوسف ته مخامخ کښېنولے شوى وُو. چې کله هغوئ ته پته ولګېده چې هغوئ څنګه کښېنولے شوى دى، نو دوئ په حېرانتيا سره يو بل ته کتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1281, 'Genesis 43:34', 'Genesis', 43, 34, '&nbsp;د يوسف د دسترخوان نه هغوئ له روټۍ ورکولے شوه او د بنيامين د نورو نه يو په پينځۀ زياته مېلمستيا وشوله. نو هغوئ د يوسف سره خوړل څښل وکړل او ښۀ په سُر کښې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1282, 'Genesis 44:1', 'Genesis', 44, 1, '&nbsp;يوسف د خپل کور مشر خِدمتګار له حُکم ورکړو چې، ”د هغه کسانو بوجۍ د غلې نه دومره ډکې کړئ چې هغوئ څومره وړلے شى او د هر يو کس روپۍ د هغۀ د بوجۍ په خولۀ کښې کېږدئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1283, 'Genesis 44:2', 'Genesis', 44, 2, '&nbsp;زما د سپينو زرو جام د کشر ورور د بوجۍ په خولۀ کښې کېږده او ورسره هغه د غلې روپۍ هم کېږده.“ نو هم هغه شان يې وکړل چې څنګه ورته وئيلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1284, 'Genesis 44:3', 'Genesis', 44, 3, '&nbsp;بل سحر وختى، د هغۀ وروڼه د خپلو خرونو سره په خپله مخه لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1285, 'Genesis 44:4', 'Genesis', 44, 4, '&nbsp;چې کله دوئ د ښار نه لږ غوندې لرې لاړل، نو يوسف د خپل کور مشر خِدمتګار ته ووئيل، ”په هغه کسانو پسې زر لاړ شه. چې کله تۀ هغوئ ته ورسېږې نو د هغوئ نه تپوس وکړه چې، تاسو د ښو په بدل کښې بد ولې کړى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1286, 'Genesis 44:5', 'Genesis', 44, 5, '&nbsp;تاسو زما د نېک د سپينو زرو جام ولې پټ کړے دے؟ دا هغه جام دے چې په کوم کښې هغه څښى او د فال دپاره يې استعمالوى. دا تاسو غلط کار کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1287, 'Genesis 44:6', 'Genesis', 44, 6, '&nbsp;چې کله خِدمتګار هغوئ له ورورسېدلو، هم هغه خبرې يې ورته وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1288, 'Genesis 44:7', 'Genesis', 44, 7, '&nbsp;هغوئ هغۀ ته ووئيل، ”صاحِبه، داسې خبرې تۀ ولې کوې؟ مونږ قسم کوُو چې مونږ داسې کار نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1289, 'Genesis 44:8', 'Genesis', 44, 8, '&nbsp;تاسو ته پته ده چې مونږ د کنعان د مُلک نه هغه روپۍ تاسو له واپس راوړې چې مونږ د بوجو په خُلو کښې وموندلې. نو بيا مونږ څنګه ستا د نېک د کور نه سرۀ يا سپين زر پټولے شُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1290, 'Genesis 44:9', 'Genesis', 44, 9, '&nbsp;صاحِبه، کۀ په مونږ کښې د چا سره هغه وموندے شو، نو هغه به مړ کړے شى او مونږ نور ټول به د خپل نېک غلامان شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1291, 'Genesis 44:10', 'Genesis', 44, 10, '&nbsp;هغه ووئيل، ”ټيک ده، خو د چا سره چې جام وموندے شى نو صِرف هغه به زما غلام شى او نور خلاص يئ تلے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1292, 'Genesis 44:11', 'Genesis', 44, 11, '&nbsp;نو هغوئ زر زر خپلې بوجۍ زمکې ته راکوزې کړې او هر يو کس خپله بوجۍ کولاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1293, 'Genesis 44:12', 'Genesis', 44, 12, '&nbsp;د يوسف خِدمتګار هغوئ د مشر ورور نه واخله تر کشر پورې ټول ښۀ ولټول او جام د بنيامين په بوجۍ کښې راووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1294, 'Genesis 44:13', 'Genesis', 44, 13, '&nbsp;د هغۀ وروڼو د خفګان نه خپلې جامې وشلولې، خرونه يې بار کړل او ښار ته واپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1295, 'Genesis 44:14', 'Genesis', 44, 14, '&nbsp;چې کله يهوداه او د هغۀ وروڼه د يوسف کور ته راغلل، نو هغه تر اوسه پورې هلته وو. او هغوئ د هغۀ په مخکښې په زمکه پرېوتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1296, 'Genesis 44:15', 'Genesis', 44, 15, '&nbsp;او يوسف ورته وفرمائيل، ”تاسو څۀ کړى دى؟ تاسو ته پته نۀ وه چې زما په شان سړے په فال څيزونه معلوموى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1297, 'Genesis 44:16', 'Genesis', 44, 16, '&nbsp;يهوداه ورته ووئيل، ”صاحِبه، مونږ تا ته څۀ ووايو؟ مونږ څۀ وئيلے شُو؟ مونږ د خپل ځان صفائى څنګه پېش کړُو؟ خُدائ پاک زمونږ غلطى راڅرګنده کړې ده. اوس به مونږ ټول سره د هغه وروره چې جام ورسره نيولے شوے دے ستا غلامان شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1298, 'Genesis 44:17', 'Genesis', 44, 17, '&nbsp;يوسف ورته وفرمائيل، ”نه، زۀ به هيڅکله هم داسې ونۀ کړم، هم هغه يو به زما غلام وى چې د چا سره جام راوتلے وو. باقى نور په خېر سره خپل پلار ته واپس تلے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1299, 'Genesis 44:18', 'Genesis', 44, 18, '&nbsp;يهوداه يوسف ته ورنزدې شو او ورته يې ووئيل، ”اے نېکه، زۀ تا ته سوال کوم چې خپل خِدمتګار له اجازت ورکړه، چې زۀ د خپل نېک په غوږ کښې يوه خبره وکړم. ما ته مۀ غصه کېږه، تۀ د فِرعون برابر يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1300, 'Genesis 44:19', 'Genesis', 44, 19, '&nbsp;نېکه، تا زمونږ نه تپوس وکړو چې ستاسو پلار يا بل ورور هم شته؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');